    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: Which of the following is the most significant risk factor for developing Pre-eclampsia?', '["Obesity", "Prior history of pre-eclampsia", "Multiple gestation", "First pregnancy (nulliparity)"]', 1, 'While nulliparity is a common risk, a prior history is the strongest predictor. (ACOG)'),
    (v_topic_id, '2: What is the current ACOG definition of "Superimposed Pre-eclampsia" in a woman with chronic hypertension?', '["Sudden increase in blood pressure", "New-onset proteinuria or a sudden increase in previously stable proteinuria", "Development of severe features like low platelets or liver enzyme elevation", "Both B and C"]', 3, 'Requires new evidence of end-organ damage or worsening protein excretion. (ACOG)'),
    (v_topic_id, '3: A woman at 30 weeks has BP 155/95 and 2+ proteinuria. She is asymptomatic. What is the most appropriate management?', '["Immediate delivery", "Hospitalization for evaluation and monitoring", "Strict bed rest at home", "Oral antihypertensives and discharge"]', 1, 'Pre-eclampsia without severe features at < 37 weeks requires close observation, usually in a hospital initially. (Williams)'),
    (v_topic_id, '4: What is the recommended aspirin dose for women at high risk of pre-eclampsia to reduce the risk of the condition?', '["81 mg daily starting at 12-28 weeks", "325 mg daily", "81 mg daily in the 3rd trimester only", "No role for aspirin"]', 0, 'Low-dose aspirin reduces the risk by ~15-20%. (USPSTF/ACOG)'),
    (v_topic_id, '5: Which of the following is NOT considered a "Severe Feature" of pre-eclampsia according to current criteria?', '["Platelet count < 100,000", "Serum creatinine > 1.1 mg/dL or doubling", "Proteinuria > 5 grams per 24 hours", "Pulmonary edema"]', 2, 'ACOG removed "massive proteinuria" (> 5g) as a severe feature because it doesn''t correlate well with outcomes. (ACOG)'),
    (v_topic_id, '6: Magnesium Sulfate is primarily excreted by the:', '["Liver", "Kidneys", "Lungs", "Gastrointestinal tract"]', 1, 'In patients with renal insufficiency, the dose must be adjusted or monitored closely (serum levels) to avoid toxicity. (Gabbe)'),
    (v_topic_id, '7: What is the first sign of Magnesium Toxicity?', '["Respiratory depression", "Loss of deep tendon reflexes (patellar reflex)", "Cardiac arrest", "Oliguria"]', 1, 'Reflexes disappear at levels around 7-10 mEq/L. (Williams)'),
    (v_topic_id, '8: A woman at 32 weeks gestation has an eclamptic seizure. What is the most important initial step?', '["Immediate C-section", "Maintain airway, oxygenation, and prevent maternal injury", "Administer Valium", "Check fetal heart tones"]', 1, 'ABC first. The seizure is usually self-limiting. (Beckmann)'),
    (v_topic_id, '9: After stabilizing a woman who had an eclamptic seizure, what is the definitive management?', '["Magnesium sulfate and continue pregnancy until 34 weeks", "Magnesium sulfate and induction of labor or C-section regardless of gestational age", "Steroids and wait 48 hours", "Send home on bed rest"]', 1, 'Eclampsia is an absolute indication for delivery. (ACOG)'),
    (v_topic_id, '10: HELLP Syndrome is most commonly associated with which of the following complications?', '["Placental abruption", "Acute renal failure", "Subcapsular liver hematoma/rupture", "All of the above"]', 3, 'A severe systemic disease involving microvascular damage. (Williams)'),
    (v_topic_id, '11: What is the classic laboratory finding of "Hemolysis" in HELLP syndrome?', '["Elevated Indirect Bilirubin and Schistocytes on peripheral smear", "Elevated Direct Bilirubin", "High Haptoglobin", "Normal LDH"]', 0, 'LDH will also be elevated (> 600 U/L). (Gabbe)'),
    (v_topic_id, '12: At what platelet count is a woman with pre-eclampsia typically considered a candidate for platelet transfusion during a C-section?', '["< 100,000", "< 50,000", "< 20,000", "< 10,000"]', 1, 'Standard threshold for surgical intervention in many centers. (ACOG)'),
    (v_topic_id, '13: Which of the following is a risk factor for "Gestational Diabetes"?', '["Previous history of GDM", "PCOS", "Ethnicity (Hispanic, African American, Asian)", "All of the above"]', 3, 'Also includes maternal age > 35 and obesity. (Williams)'),
    (v_topic_id, '14: If a woman has a 1-hour GCT of 220 mg/dL, what is the next step?', '["Perform 3-hour GTT", "Diagnose GDM immediately", "Repeat 1-hour test", "Check HbA1c"]', 1, 'Values > 200 mg/dL (or 190 in some guidelines) are considered diagnostic without the 3-hour test. (ACOG)'),
    (v_topic_id, '15: What is the primary reason why maternal hyperglycemia leads to fetal macrosomia?', '["Maternal insulin crosses the placenta", "Fetal hyperglycemia stimulates fetal insulin production (an anabolic growth factor)", "Placental hormones", "Increased fetal cortisol"]', 1, 'Insulin does NOT cross the placenta, but glucose does. (Beckmann)'),
    (v_topic_id, '16: A woman with pre-gestational Type 1 Diabetes is at significantly higher risk for what in the first trimester?', '["Spontaneous abortion and congenital malformations", "Pre-eclampsia", "Macrosomia", "Polyhydramnios"]', 0, 'Risk is directly related to glycemic control (HbA1c) during organogenesis. (Gabbe)'),
    (v_topic_id, '17: "Neonatal Hypoglycemia" in infants of diabetic mothers is caused by:', '["Lack of glucose in breast milk", "Hyperinsulinemia in the neonate persisting after the glucose source (placenta) is removed", "Neonatal sepsis", "Fetal growth restriction"]', 1, 'The baby''s pancreas is used to high glucose levels and keeps pumping out insulin. (Williams)'),
    (v_topic_id, '18: Which of the following is the most common heart defect in infants of diabetic mothers?', '["Tetralogy of Fallot", "Ventricular Septal Defect (VSD) and Transposition of the Great Arteries", "Atrial Septal Defect", "Coarctation of the aorta"]', 1, 'Also associated with hypertrophic cardiomyopathy (septal hypertrophy). (Gabbe)'),
    (v_topic_id, '19: "Sacral Agenesis" (Caudal Regression Syndrome) is highly specific for:', '["Maternal alcohol use", "Maternal pre-gestational diabetes", "Folic acid deficiency", "Toxoplasmosis"]', 1, 'A rare but classic association. (Beckmann)'),
    (v_topic_id, '20: What is the recommended mode of delivery for a diabetic woman with an estimated fetal weight of 4600 grams?', '["Routine vaginal delivery", "Forceps delivery", "Offer Cesarean section to reduce risk of shoulder dystocia", "Vacuum extraction"]', 2, 'ACOG recommends offering C-section if EFW > 4500g in diabetics (5000g in non-diabetics). (ACOG)'),
    (v_topic_id, '21: Which of the following is an "Early" sign of placental abruption on fetal monitoring?', '["Late decelerations or bradycardia", "Accelerations", "Early decelerations", "Sinusoidal rhythm"]', 0, 'Signs of fetal distress due to reduced placental surface area for gas exchange. (Williams)'),
    (v_topic_id, '22: Severe placental abruption can lead to "DIC" (Disseminated Intravascular Coagulation) due to the release of:', '["Oxytocin", "Tissue Factor (Thromboplastin)", "Estrogen", "Progesterone"]', 1, 'Released from the damaged placenta/decidua into the maternal circulation. (Gabbe)'),
    (v_topic_id, '23: What is the most important clinical finding that differentiates placental abruption from placenta previa?', '["The amount of bleeding", "The presence of abdominal pain and uterine tenderness", "Maternal age", "Fetal heart rate"]', 1, 'Previa is typically painless; Abruption is painful/tender. (Beckmann)'),
    (v_topic_id, '24: A woman at 28 weeks has a placenta previa. She is currently stable after a small bleed. What is the management?', '["Immediate C-section", "Expectant management (bed rest, steroids for lungs)", "Induction of labor", "Discharge home with no restrictions"]', 1, 'The goal is to reach 36-37 weeks if the mother and fetus remain stable. (ACOG)'),
    (v_topic_id, '25: In "Placenta Accreta," the placenta is attached to:', '["The decidua only", "The myometrium", "The bladder", "The cervix"]', 1, 'Accreta (to), Increta (in), Percreta (through). (Williams)'),
    (v_topic_id, '26: What is the primary management for a placenta accreta discovered at the time of Cesarean section?', '["Manual removal of the placenta", "Hysterectomy with the placenta left in situ", "D&C", "Uterine artery embolization"]', 1, 'Attempting manual removal often causes life-threatening hemorrhage. (ACOG)'),
    (v_topic_id, '27: "Preterm Labor" is defined as regular contractions with cervical change before:', '["34 weeks", "37 weeks", "40 weeks", "42 weeks"]', 1, 'Cervical dilation > 2cm or effacement > 80% with regular contractions. (ACOG)'),
    (v_topic_id, '28: What is the most common reason for a "false positive" fetal fibronectin (fFN) test?', '["Fetal movement", "Recent sexual intercourse or vaginal exam in the last 24 hours", "Dehydration", "Eating a heavy meal"]', 1, 'Semen and lubricant can interfere with the assay. (Gabbe)'),
    (v_topic_id, '29: The "negative predictive value" (NPV) of a fetal fibronectin test means:', '["If the test is negative, the woman is unlikely to deliver in the next 1-2 weeks", "If the test is positive, the woman will deliver in 24 hours", "The test is useless", "The baby is healthy"]', 0, 'NPV is > 95% for delivery within 7-14 days. (ACOG)'),
    (v_topic_id, '30: Which medication used for tocolysis is a Beta-2 agonist?', '["Nifedipine", "Indomethacin", "Terbutaline", "Magnesium sulfate"]', 2, 'Common side effects include tachycardia, palpitations, and pulmonary edema. (Williams)'),
    (v_topic_id, '31: "Indomethacin" (NSAID) should generally not be used for tocolysis after how many weeks gestation?', '["28 weeks", "32 weeks", "34 weeks", "37 weeks"]', 1, 'Risk of premature closure of the ductus arteriosus increases significantly after 32 weeks. (ACOG)'),
    (v_topic_id, '32: A woman at 31 weeks has PPROM. She has a fever of 101F, uterine tenderness, and fetal tachycardia. What is the diagnosis?', '["Normal labor", "Chorioamnionitis (Intra-amniotic infection)", "Placental abruption", "UTI"]', 1, 'Requires immediate broad-spectrum antibiotics and delivery. (Beckmann)'),
    (v_topic_id, '33: What is the standard management for "stable" PPROM at 30 weeks gestation?', '["Immediate delivery", "Expectant management with latency antibiotics and steroids", "Induction of labor", "Cerclage placement"]', 1, 'Balance the risk of infection against the risk of prematurity. (ACOG)'),
    (v_topic_id, '34: At what gestational age does the risk of neonatal complications from PPROM (e.g., RDS, sepsis) generally outweigh the risks of continuing the pregnancy?', '["24 weeks", "34 weeks", "37 weeks", "40 weeks"]', 1, 'Most guidelines recommend delivery at 34 weeks for PPROM. (ACOG)'),
    (v_topic_id, '35: Which of the following is a symptom of "Umbilical Cord Prolapse"?', '["Severe abdominal pain", "Sudden fetal bradycardia or deep variable decelerations after ROM", "Maternal fever", "High blood pressure"]', 1, 'An obstetric emergency; the cord is compressed between the fetus and the pelvis. (Williams)'),
    (v_topic_id, '36: What is the immediate management for a cord prolapse?', '["Manual elevation of the presenting part and emergent Cesarean section", "Wait for vaginal delivery", "Administer oxytocin", "Try to push the cord back in"]', 0, 'Keep your hand in the vagina pushing the head up until the baby is delivered via C-section! (ACOG)'),
    (v_topic_id, '37: "Incompetent Cervix" (Cervical Insufficiency) is most commonly diagnosed after:', '["One preterm birth", "One first-trimester miscarriage", "One or more second-trimester pregnancy losses (painless dilation)", "A positive fFN test"]', 2, 'History-based diagnosis is common. (Beckmann)'),
    (v_topic_id, '38: In a twin-to-twin transfusion syndrome (TTTS), the "Recipient" twin is at risk for:', '["Polyhydramnios, heart failure (hydrops), and polycythemia", "Oligohydramnios and anemia", "Macrosomia only", "IUGR"]', 0, 'Receives too much blood from the donor. (Gabbe)'),
    (v_topic_id, '39: What is the most effective treatment for Stage II-IV TTTS?', '["Serial amnioreduction", "Fetoscopic laser photocoagulation of placental anastomoses", "Delivery at 24 weeks", "Bed rest"]', 1, 'Ablating the shared vessels stops the transfusion. (Williams)'),
    (v_topic_id, '40: Which of the following is a maternal risk of "Multiple Gestation"?', '["Hyperemesis gravidarum", "Postpartum hemorrhage (uterine atony)", "Pre-eclampsia", "All of the above"]', 3, 'The larger uterine volume and placental mass increase all these risks. (ACOG)'),
    (v_topic_id, '41: A woman with "Rh Alloimmunization" (anti-D antibodies) has a titer of 1:32. What is the next step?', '["Immediate delivery", "Monitor fetal middle cerebral artery (MCA) peak systolic velocity via Doppler", "Repeat titer in 1 week", "Give RhoGAM"]', 1, 'MCA Doppler assesses the risk of fetal anemia. (ACOG)'),
    (v_topic_id, '42: Why does an anemic fetus have increased flow velocity in the Middle Cerebral Artery (MCA)?', '["The brain needs more blood", "Decreased blood viscosity and compensatory increase in cardiac output", "The baby is sleeping", "High blood pressure"]', 1, 'A reliable non-invasive way to detect fetal anemia. (Gabbe)'),
    (v_topic_id, '43: If a fetus is found to be severely anemic (via cordocentesis or suspected via MCA Doppler), what is the treatment?', '["Immediate delivery", "Intrauterine Fetal Blood Transfusion", "Maternal iron supplements", "Steroids"]', 1, 'Transfusion into the umbilical vein can be done from 18 to 35 weeks. (Williams)'),
    (v_topic_id, '44: "ABO Incompatibility" (e.g., Mother O, Baby A) typically results in:', '["Severe hydrops in utero", "Mild neonatal jaundice", "Stillbirth", "Erythroblastosis fetalis"]', 1, 'Less severe than Rh disease because A/B antigens are expressed on many tissues, not just RBCs. (Beckmann)'),
    (v_topic_id, '45: Which of the following is a cause of "Non-Immune Hydrops"?', '["Fetal cardiac arrhythmias (e.g., SVT)", "Chromosomal anomalies (e.g., Turner syndrome)", "Parvovirus B19", "All of the above"]', 3, 'Anything that causes fetal heart failure or lymphatic obstruction. (Gabbe)'),
    (v_topic_id, '46: A woman at 39 weeks has "Post-term" pregnancy (42+ weeks). What is the primary fetal risk?', '["Macrosomia", "Dysmaturity syndrome and Oligohydramnios", "Meconium aspiration", "All of the above"]', 3, 'Placental function declines after 42 weeks. (ACOG)'),
    (v_topic_id, '47: "Meconium Stained Amniotic Fluid" is most common in which pregnancies?', '["Preterm", "Term", "Post-term", "Ectopic"]', 2, 'Found in ~25-30% of post-term pregnancies. (Williams)'),
    (v_topic_id, '48: Which of the following is an indication for "Induction of Labor" in a post-term patient?', '["Oligohydramnios (AFI < 5)", "Non-reassuring NST", "Reaching 41-42 weeks", "All of the above"]', 3, 'To prevent stillbirth and other complications. (ACOG)'),
    (v_topic_id, '49: "Intrahepatic Cholestasis of Pregnancy" is associated with an increased risk of:', '["Maternal liver failure", "Unexplained stillbirth", "Maternal hypertension", "Neonatal diabetes"]', 1, 'Delivery at 36-37 weeks is often recommended due to this risk. (ACOG)'),
    (v_topic_id, '50: A "Bishop Score" of 4 indicates that the cervix is:', '["Ready for induction with oxytocin", "Unripe (may require prostaglandins or a balloon for ripening)", "Completely effaced", "Closed"]', 1, 'Score < 6 usually requires ripening. (Beckmann)'),
    (v_topic_id, '51: Which of the following is a "mechanical" method for cervical ripening?', '["Misoprostol", "Dinoprostone", "Foley catheter (balloon) placed in the cervix", "Nipple stimulation"]', 2, 'Physical stretching of the cervix and release of local prostaglandins. (ACOG)'),
    (v_topic_id, '52: What is the primary risk of using "Misoprostol" (PGE1) for cervical ripening in a woman with a previous C-section?', '["None", "Uterine rupture", "Nausea", "Hyperemesis"]', 1, 'Misoprostol is CONTRAINDICATED for induction/ripening in women with a scarred uterus. (ACOG)'),
    (v_topic_id, '53: "Shoulder Dystocia" is most common in which of the following scenarios?', '["Breech presentation", "Infants of diabetic mothers (macrosomia)", "Preterm infants", "Twins"]', 1, 'Disproportionate growth of the shoulders. (Williams)'),
    (v_topic_id, '54: A "Wood''s Screw Maneuver" during shoulder dystocia involves:', '["Pulling on the head", "Rotating the posterior shoulder", "Hyperflexing the hips", "Applying fundal pressure"]', 1, 'FUNDAL pressure is contraindicated in shoulder dystocia as it further impacts the shoulder. (Gabbe)'),
    (v_topic_id, '55: "Zavanelli Maneuver" is a last-resort procedure for shoulder dystocia involving:', '["Breaking the clavicle", "Flexing the head back into the vagina and performing emergent C-section", "Symphysiotomy", "Giving more oxytocin"]', 1, 'Associated with high morbidity but may be life-saving. (Williams)'),
    (v_topic_id, '56: What is the most common cause of "Uterine Inversion"?', '["Prior C-section", "Excessive cord traction and fundal pressure before placental separation", "Multiple gestation", "Oxytocin use"]', 1, 'The uterus is "turned inside out" and protrudes from the vagina. (Beckmann)'),
    (v_topic_id, '57: What is the initial step in managing a "Uterine Inversion"?', '["Give oxytocin immediately", "Manual replacement of the fundus (after stopping oxytocin and giving relaxants if needed)", "Hysterectomy", "D&C"]', 1, 'Must replace the uterus before the cervix constricts around it. (ACOG)'),
    (v_topic_id, '58: A "Couvelaire Uterus" (bruised/bluish uterus) is found during C-section after a placental abruption. What is the primary concern?', '["Infection", "Uterine atony leading to postpartum hemorrhage", "Malignancy", "None"]', 1, 'Blood in the myometrium prevents effective contraction. (Williams)'),
    (v_topic_id, '59: What is the most common maternal complication of "Maternal Obesity"?', '["Gestational diabetes", "Hypertension/Pre-eclampsia", "Cesarean delivery and wound complications", "All of the above"]', 3, 'Obesity significantly increases obstetric risk across the board. (ACOG)'),
    (v_topic_id, '60: A woman with "Lupus" (SLE) should ideally wait until she has been in remission for how long before conceiving?', '["1 month", "6 months", "2 years", "Never conceive"]', 1, 'Active disease at conception is associated with poor outcomes. (Gabbe)'),
    (v_topic_id, '61: "Neonatal Lupus" is caused by the transplacental passage of which antibodies?', '["Anti-dsDNA", "Anti-Ro (SSA) and Anti-La (SSB)", "Anti-Smith", "Antiphospholipid"]', 1, 'Associated with congenital heart block in the neonate. (Beckmann)'),
    (v_topic_id, '62: "Antiphospholipid Syndrome" (APS) in pregnancy is treated with:', '["Steroids", "Low-dose Aspirin and Heparin (LMWH or Unfractionated)", "Warfarin", "Methotrexate"]', 1, 'To prevent placental thrombosis and recurrent loss. (ACOG)'),
    (v_topic_id, '63: A pregnant woman has a suspected "Pulmonary Embolism." What is the first-line imaging study after a normal CXR?', '["CT Pulmonary Angiogram (CTPA) or V/Q scan", "MRI", "Abdominal US", "ECG only"]', 0, 'Diagnosis must be confirmed; radiation risk to the fetus is minimal with proper shielding. (ACOG)'),
    (v_topic_id, '64: What is the preferred anticoagulant for the treatment of DVT/PE in pregnancy?', '["Warfarin", "Low Molecular Weight Heparin (e.g., Enoxaparin)", "Dabigatran", "Aspirin"]', 1, 'Heparins do not cross the placenta. (ACOG)'),
    (v_topic_id, '65: A woman has "mitral stenosis." Why is she at highest risk during labor and immediately postpartum?', '["Hormonal changes", "Fluid shifts and increased cardiac output (autotransfusion)", "Pain", "Nausea"]', 1, 'The sudden increase in venous return can lead to acute pulmonary edema. (Williams)'),
    (v_topic_id, '66: "Peripartum Cardiomyopathy" is defined as heart failure occurring:', '["In the 1st trimester", "In the last month of pregnancy or first 5 months postpartum, with no prior history", "During childhood", "Only after C-section"]', 1, 'Associated with a dilated heart and reduced ejection fraction. (Gabbe)'),
    (v_topic_id, '67: Which of the following is a risk factor for "Peripartum Cardiomyopathy"?', '["Advanced maternal age", "Multiple gestation", "Pre-eclampsia", "All of the above"]', 3, 'The etiology is unknown but likely multifactorial. (Williams)'),
    (v_topic_id, '68: Maternal "Hyperthyroidism" (Graves disease) is treated with which medication in the FIRST trimester?', '["Methimazole", "Propylthiouracil (PTU)", "Radioactive iodine", "Levothyroxine"]', 1, 'PTU is preferred in the 1st trimester to avoid Methimazole-associated embryopathy (aplasia cutis). (ACOG)'),
    (v_topic_id, '69: Maternal "Hypothyroidism" is associated with an increased risk of:', '["Pre-eclampsia", "Placental abruption", "Lowered IQ and developmental delay in the offspring", "All of the above"]', 3, 'Fetal brain development depends on maternal T4 in early pregnancy. (ACOG)'),
    (v_topic_id, '70: A pregnant woman at 34 weeks presents with acute RUQ pain, nausea, jaundice, and severe hypoglycemia. Diagnosis?', '["Pre-eclampsia", "Acute Fatty Liver of Pregnancy (AFLP)", "HELLP syndrome", "Cholecystitis"]', 1, 'Hypoglycemia is a key finding differentiating AFLP from HELLP. (Gabbe)'),
    (v_topic_id, '71: What is the genetic defect often found in the FETUS of a woman with Acute Fatty Liver of Pregnancy?', '["LCHAD (Long-chain 3-hydroxyacyl-CoA dehydrogenase) deficiency", "Trisomy 21", "Cystic fibrosis", "None"]', 0, 'The fetus cannot oxidize fatty acids, leading to toxic build-up in the mother''s liver. (Williams)'),
    (v_topic_id, '72: "Asymptomatic Bacteriuria" in pregnancy must be treated because of the high risk (25-40%) of progressing to:', '["Preterm labor", "Pyelonephritis", "Cystitis", "Renal failure"]', 1, 'Due to physiologic changes in the urinary tract. (ACOG)'),
    (v_topic_id, '73: A pregnant woman has "Pyelonephritis." What is the standard management?', '["Oral antibiotics at home", "Inpatient hospitalization, IV fluids, and IV antibiotics", "Wait for culture results", "Induction of labor"]', 1, 'High risk of maternal sepsis and ARDS. (Williams)'),
    (v_topic_id, '74: "Pruritic Urticarial Papules and Plaques of Pregnancy" (PUPPP) is usually treated with:', '["Antivirals", "Topical steroids and antihistamines", "Immediate delivery", "Antibiotics"]', 1, 'A benign but very itchy condition. (Beckmann)'),
    (v_topic_id, '75: "Pemphigoid Gestationis" (Herpes Gestationis) is an autoimmune bullous disease of pregnancy that involves:', '["The face", "The umbilicus and surrounding skin", "The palms and soles", "The mouth"]', 1, 'Unlike PUPPP, it often involves the umbilicus and may require oral steroids. (Gabbe)'),
    (v_topic_id, '76: Which TORCH infection is associated with "limb hypoplasia," "skin scarring," and "microcephaly"?', '["Rubella", "Varicella (Congenital Varicella Syndrome)", "CMV", "Syphilis"]', 1, 'Occurs if the mother is infected in the first half of pregnancy. (Williams)'),
    (v_topic_id, '77: If a woman is exposed to "Rubella" during pregnancy and is non-immune, what is the recommendation?', '["Immediate vaccination", "Counseling about fetal risks (vaccination is contraindicated)", "VZIG", "Acyclovir"]', 1, 'MMR is a live vaccine and is contraindicated in pregnancy. (CDC)'),
    (v_topic_id, '78: A woman has a "primary" HSV infection during the third trimester. What is the risk of vertical transmission?', '["< 1%", "5%", "30-50%", "100%"]', 2, 'Primary infections have much higher viral shedding and lower maternal antibodies. (ACOG)'),
    (v_topic_id, '79: Which of the following is the most common cause of maternal death worldwide?', '["Infection", "Postpartum hemorrhage", "Hypertension", "Unsafe abortion"]', 1, 'PPH is a leading cause of mortality in low-resource settings. (WHO)'),
    (v_topic_id, '80: "Amniotic Fluid Embolism" is characterized by a "triad" of:', '["Fever, pain, bleeding", "Hypoxia, hypotension, and coagulopathy (DIC)", "High BP, protein, seizures", "Vomiting, jaundice, itching"]', 1, 'Management is purely supportive/resuscitative. (ACOG)'),
    (v_topic_id, '81: "Septic Pelvic Thrombophlebitis" (SPT) is a postpartum complication characterized by:', '["Persistent fever despite broad-spectrum antibiotics", "Leg swelling", "Heavy bleeding", "Breast pain"]', 0, 'Often a "diagnosis of exclusion" that responds to heparin. (Williams)'),
    (v_topic_id, '82: "Endometritis" after C-section is most effectively prevented by:', '["Washing the vagina", "Single dose of prophylactic IV antibiotics before the incision", "Oral antibiotics for 1 week", "Postoperative steroids"]', 1, 'Standard of care for all C-sections. (ACOG)'),
    (v_topic_id, '83: "Vasa Previa" vessels are unprotected by:', '["The placenta", "The amnion", "Wharton''s jelly", "The chorion"]', 2, 'This makes them extremely fragile. (Gabbe)'),
    (v_topic_id, '84: What is the classic ultrasound appearance of a "Complete Mole"?', '["Snowstorm" or "Swiss Cheese" pattern with no fetus", "Multiple fetuses", "Large placenta", "Normal fetus"]', 0, 'Hydropic degeneration of all villi. (Beckmann)'),
    (v_topic_id, '85: A "Theca Lutein Cyst" found on the ovary during a molar pregnancy is caused by:', '["Infection", "Extremely high levels of hCG", "Endometriosis", "Ovarian cancer"]', 1, 'Usually regresses once the mole is evacuated. (Williams)'),
    (v_topic_id, '86: A woman at 38 weeks with "Severe Pre-eclampsia" has a BP of 175/115. What is the first-line IV medication to lower BP?', '["Labetalol or Hydralazine", "Magnesium sulfate", "Lisinopril", "Nitroprusside"]', 0, 'Goal is to reduce the risk of stroke. (ACOG)'),
    (v_topic_id, '87: "Postpartum Thyroiditis" typically presents with a phase of:', '["Hyperthyroidism followed by hypothyroidism", "Permanent hypothyroidism", "Hyperthyroidism only", "Goiter only"]', 0, 'Occurs within the first year postpartum. (ACOG)'),
    (v_topic_id, '88: Which of the following is a risk factor for "Placental Abruption"?', '["Cocaine use", "Trauma", "Smoking", "All of the above"]', 3, 'Vascular disruption is the common mechanism. (Williams)'),
    (v_topic_id, '89: "Chronic Hypertension" increases the risk of which of the following?', '["Superimposed pre-eclampsia", "IUGR", "Placental abruption", "All of the above"]', 3, 'Requires baseline labs (Cr, Protein, LFTs) at the first visit. (ACOG)'),
    (v_topic_id, '90: In a patient with "Asthma," which medication for PPH should be avoided?', '["Oxytocin", "Methylergonovine", "Carboprost (Hemabate)", "Misoprostol"]', 2, 'Prostaglandin F2-alpha causes bronchoconstriction. (Beckmann)'),
    (v_topic_id, '91: "Uterine Atony" is more likely in which of the following?', '["Polyhydramnios", "Multiple gestation", "Prolonged labor", "All of the above"]', 3, 'Conditions that over-distend or exhaust the myometrium. (ACOG)'),
    (v_topic_id, '92: "B-Lynch Suture" is a surgical technique used to:', '["Repair a uterine rupture", "Treat refractory postpartum hemorrhage by compressing the uterus", "Close a C-section incision", "Cerclage"]', 1, 'A "suspenders" type stitch that keeps the uterus compressed. (Williams)'),
    (v_topic_id, '93: "Placenta Increta" occurs when the placenta invades:', '["The decidua", "Into the myometrium", "Through the serosa", "The cervix"]', 1, 'Requires surgical management. (Gabbe)'),
    (v_topic_id, '94: Which of the following is a symptom of "Magnesium Toxicity"?', '["Nausea and flushing", "Decreased urine output", "Respiratory rate < 12/min", "All of the above"]', 3, 'Flushing is a common side effect, but respiratory depression is a sign of toxicity. (Williams)'),
    (v_topic_id, '95: A woman at 32 weeks has "PPROM" and is being managed expectantly. She develops "variable decelerations" on NST. This is likely due to:', '["Cord compression due to oligohydramnios", "Fetal sleep", "Infection", "Steroids"]', 0, 'Loss of fluid leads to cord vulnerability. (ACOG)'),
    (v_topic_id, '96: "Fetal Hydrops" is defined as fluid accumulation in at least how many fetal compartments?', '["One", "Two (e.g., ascites and pleural effusion)", "Three", "Four"]', 1, 'Diagnostic criterion for hydrops fetalis. (Gabbe)'),
    (v_topic_id, '97: "Fetomaternal Hemorrhage" (FMH) can cause fetal:', '["Anemia", "Hydrops", "Stillbirth", "All of the above"]', 3, 'Large hemorrhages (> 30 mL) are rare but serious. (Williams)'),
    (v_topic_id, '98: In the management of "Preterm Labor," what is the primary role of Tocolytics?', '["To deliver a healthy baby at term", "To provide 48 hours for steroid administration and maternal transport", "To cure the underlying cause", "To prevent infection"]', 1, 'Do not significantly improve long-term outcomes on their own. (ACOG)'),
    (v_topic_id, '99: A woman with "Graves Disease" has a high titer of Thyroid Stimulating Immunoglobulin (TSI). What is the risk to the fetus?', '["None", "Transient neonatal hyperthyroidism (TSI crosses the placenta)", "Fetal goiter", "Cleft palate"]', 1, 'Antibodies can stimulate the fetal thyroid. (Gabbe)'),
    (v_topic_id, '100: What is the most common cause of "fetal death" in a woman with an eclamptic seizure?', '["Maternal hypoxia", "Placental abruption (often occurs concurrently)", "Fetal trauma", "Infection"]', 1, 'Abruption occurs in ~10-15% of eclamptic cases. (Williams)');
