BEGIN;

DO $$ 
DECLARE
    v_topic_id UUID;
BEGIN
    -- Ensure the topic exists
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'obgyn-pregnancy-complications' LIMIT 1;
    
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic "obgyn-pregnancy-complications" not found.';
    END IF;

    -- Idempotent delete
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- Insert MCQs (Batch 1: 1-100)

END $$;

COMMIT;
